// @FIGURE_CODE_BEGIN
// cylinder cap outlines → Line loop/arc sampled from true circles in the horizontal XZ plane, black
// cylinder silhouette edges → two vertical Line segments tangent to the projected circular caps, black
// solid radius arrow → Line plus one ConeGeometry arrowhead, black
// solid height arrow → Line plus two ConeGeometry arrowheads, black
// invisible solid picking body → CylinderGeometry with transparent material
// net cap circles → two Line loops drawn in a screen-parallel plane, black
// net lateral rectangle → Line rectangle in a screen-parallel plane, black
// net dimension arrows → Line plus ConeGeometry arrowheads for h and 2πr, black
// net radius arrow → Line plus one ConeGeometry arrowhead inside one cap circle, black
// formula association strokes → short Line connector/brace strokes, black

const black = 0x000000;
const solidGroup = new THREE.Group();
const netGroup = new THREE.Group();
scene.add(solidGroup);
scene.add(netGroup);

const azIso = THREE.MathUtils.degToRad(45);
const elIso = Math.asin(Math.sqrt(Math.tan(THREE.MathUtils.degToRad(30)) * Math.tan(THREE.MathUtils.degToRad(30))));
const screenRight = new THREE.Vector3(Math.sin(azIso), 0, -Math.cos(azIso)).normalize();
const screenUp = new THREE.Vector3(
  -Math.cos(azIso) * Math.sin(elIso),
  Math.cos(elIso),
  -Math.sin(azIso) * Math.sin(elIso)
).normalize();
const viewDir = new THREE.Vector3(
  Math.cos(azIso) * Math.cos(elIso),
  Math.sin(elIso),
  Math.sin(azIso) * Math.cos(elIso)
).normalize();

function makeLine(parent, opacity = 1) {
  const mat = new THREE.LineBasicMaterial({ color: black, transparent: true, opacity });
  const line = new THREE.Line(new THREE.BufferGeometry(), mat);
  parent.add(line);
  return line;
}

function setLine(line, pts) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old.dispose();
}

function circleXZ(y, r, a0, a1, n = 144) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const t = a0 + (a1 - a0) * (i / n);
    pts.push(new THREE.Vector3(r * Math.cos(t), y, r * Math.sin(t)));
  }
  return pts;
}

function screenPoint(sx, sy, normalOffset = 0) {
  return screenRight.clone().multiplyScalar(sx)
    .add(screenUp.clone().multiplyScalar(sy))
    .add(viewDir.clone().multiplyScalar(normalOffset));
}

function circleScreen(cx, cy, rr, n = 144) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const t = Math.PI * 2 * i / n;
    pts.push(screenPoint(cx + rr * Math.cos(t), cy + rr * Math.sin(t), 0));
  }
  return pts;
}

function rectScreen(cx, cy, w, h) {
  const x0 = cx - w / 2, x1 = cx + w / 2, y0 = cy - h / 2, y1 = cy + h / 2;
  return [
    screenPoint(x0, y0), screenPoint(x1, y0), screenPoint(x1, y1),
    screenPoint(x0, y1), screenPoint(x0, y0)
  ];
}

function clearGroup(g) {
  while (g.children.length) {
    const c = g.children.pop();
    c.geometry?.dispose?.();
    if (Array.isArray(c.material)) c.material.forEach(m => m.dispose?.());
    else c.material?.dispose?.();
  }
}

function addCone(parent, tip, dir, opacity = 1, size = 0.12) {
  const geom = new THREE.ConeGeometry(size * 0.34, size, 24);
  const mat = new THREE.MeshBasicMaterial({ color: black, transparent: true, opacity });
  const cone = new THREE.Mesh(geom, mat);
  cone.position.copy(tip.clone().sub(dir.clone().normalize().multiplyScalar(size / 2)));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  parent.add(cone);
  return cone;
}

function makeArrow(parent, start, end, doubleHead = false, opacity = 1, size = 0.13) {
  const g = new THREE.Group();
  parent.add(g);
  const dir = end.clone().sub(start).normalize();
  const trim = size * 0.82;
  const p0 = doubleHead ? start.clone().add(dir.clone().multiplyScalar(trim)) : start.clone();
  const p1 = end.clone().sub(dir.clone().multiplyScalar(trim));
  setLine(makeLine(g, opacity), [p0, p1]);
  addCone(g, end, dir, opacity, size);
  if (doubleHead) addCone(g, start, dir.clone().negate(), opacity, size);
  return g;
}

const solid = {
  top: makeLine(solidGroup),
  bottomFront: makeLine(solidGroup),
  leftEdge: makeLine(solidGroup),
  rightEdge: makeLine(solidGroup),
  radiusArrow: new THREE.Group(),
  heightArrow: new THREE.Group(),
  pickMesh: null
};
solidGroup.add(solid.radiusArrow, solid.heightArrow);

const net = {
  cap1: makeLine(netGroup, 0),
  cap2: makeLine(netGroup, 0),
  rect: makeLine(netGroup, 0),
  hArrow: new THREE.Group(),
  wArrow: new THREE.Group(),
  rArrow: new THREE.Group(),
  assoc1: makeLine(netGroup, 0),
  assoc2: makeLine(netGroup, 0)
};
netGroup.add(net.hArrow, net.wArrow, net.rArrow);

let rVal = 1.25;
let hVal = 2.4;
let mode = 'Solid cylinder';
let targetNetBlend = 0;
let currentNetBlend = 0;
let solidPickMesh = null;

function allMaterials(obj, arr = []) {
  obj.traverse(o => {
    if (o.material) {
      if (Array.isArray(o.material)) arr.push(...o.material);
      else arr.push(o.material);
    }
  });
  return arr;
}

function setGroupOpacity(group, opacity) {
  allMaterials(group).forEach(m => {
    m.transparent = true;
    m.opacity = opacity;
    m.needsUpdate = true;
  });
}

function rebuildArrowGroup(g, start, end, doubleHead, opacity, size) {
  clearGroup(g);
  makeArrow(g, start, end, doubleHead, opacity, size);
}

function updateGeometry(refit = true) {
  const topY = hVal / 2;
  const botY = -hVal / 2;

  setLine(solid.top, circleXZ(topY, rVal, 0, Math.PI * 2, 180));

  const frontAngle = Math.PI / 4;
  setLine(solid.bottomFront, circleXZ(botY, rVal, frontAngle - Math.PI / 2, frontAngle + Math.PI / 2, 96));

  const rightXZ = screenRight.clone().multiplyScalar(rVal);
  const leftXZ = rightXZ.clone().negate();
  setLine(solid.rightEdge, [new THREE.Vector3(rightXZ.x, topY, rightXZ.z), new THREE.Vector3(rightXZ.x, botY, rightXZ.z)]);
  setLine(solid.leftEdge, [new THREE.Vector3(leftXZ.x, topY, leftXZ.z), new THREE.Vector3(leftXZ.x, botY, leftXZ.z)]);

  rebuildArrowGroup(
    solid.radiusArrow,
    new THREE.Vector3(0, topY, 0),
    new THREE.Vector3(rightXZ.x, topY, rightXZ.z),
    false,
    1 - currentNetBlend,
    0.12
  );

  const hOff = screenRight.clone().multiplyScalar(rVal + 0.38);
  rebuildArrowGroup(
    solid.heightArrow,
    new THREE.Vector3(hOff.x, botY, hOff.z),
    new THREE.Vector3(hOff.x, topY, hOff.z),
    true,
    1 - currentNetBlend,
    0.12
  );

  if (solidPickMesh) {
    solidGroup.remove(solidPickMesh);
    solidPickMesh.geometry.dispose();
    solidPickMesh.material.dispose();
  }
  solidPickMesh = new THREE.Mesh(
    new THREE.CylinderGeometry(rVal, rVal, hVal, 64, 1, false),
    new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, depthWrite: false })
  );
  registerInteractive(solidPickMesh, {
    title: 'Cylinder surface',
    tooltip: 'Cylinder: radius r and height h',
    body: 'The surface area separates into two circular caps, 2πr², and one unwrapped side rectangle, 2πrh.'
  });
  solidGroup.add(solidPickMesh);

  const circleR = rVal * 0.55;
  const rectW = 2 * Math.PI * rVal * 0.32;
  const rectH = hVal;
  const circleX = -2.28;
  const circleGap = Math.max(0.18, 0.2 + circleR * 0.15);
  const circleY = circleR + circleGap / 2;
  const rectX = 1.0;
  const rectY = 0.12;

  setLine(net.cap1, circleScreen(circleX, circleY, circleR));
  setLine(net.cap2, circleScreen(circleX, -circleY, circleR));
  setLine(net.rect, rectScreen(rectX, rectY, rectW, rectH));

  rebuildArrowGroup(
    net.rArrow,
    screenPoint(circleX, circleY),
    screenPoint(circleX + circleR, circleY),
    false,
    currentNetBlend,
    0.095
  );

  rebuildArrowGroup(
    net.hArrow,
    screenPoint(rectX + rectW / 2 + 0.22, rectY - rectH / 2),
    screenPoint(rectX + rectW / 2 + 0.22, rectY + rectH / 2),
    true,
    currentNetBlend,
    0.095
  );

  rebuildArrowGroup(
    net.wArrow,
    screenPoint(rectX - rectW / 2, rectY - rectH / 2 - 0.22),
    screenPoint(rectX + rectW / 2, rectY - rectH / 2 - 0.22),
    true,
    currentNetBlend,
    0.095
  );

  setLine(net.assoc1, [
    screenPoint(circleX + circleR * 0.3, -circleY - circleR - 0.1),
    screenPoint(-1.15, -rectH / 2 - 0.58)
  ]);
  setLine(net.assoc2, [
    screenPoint(rectX, rectY - rectH / 2 - 0.08),
    screenPoint(1.08, -rectH / 2 - 0.58)
  ]);

  setGroupOpacity(solidGroup, 1 - currentNetBlend);
  setGroupOpacity(netGroup, currentNetBlend);
  solidPickMesh.material.opacity = 0;

  if (labelsReady) updateLabels();
  updateReadouts();

  if (refit) {
    netGroup.visible = currentNetBlend > 0.02 || targetNetBlend > 0.02;
    solidGroup.visible = currentNetBlend < 0.98 || targetNetBlend < 0.98;
    setCameraView({
      projection: 'orthographic',
      axisScreenAngles: { x: 30, z: 30 },
      rollDeg: 0,
      heightFraction: 0.68
    });
  }
}

function updateReadouts() {
  document.getElementById('radiusVal').textContent = rVal.toFixed(2);
  document.getElementById('heightVal').textContent = hVal.toFixed(2);
  const caps = 2 * Math.PI * rVal * rVal;
  const side = 2 * Math.PI * rVal * hVal;
  document.getElementById('areaOut').innerHTML =
    `S = ${caps.toFixed(2)} + ${side.toFixed(2)} = ${(caps + side).toFixed(2)}`;
}

updateGeometry(false);
netGroup.visible = false;
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.68
});

let labelsReady = false;
const labels = {
  solidR: addLabel('<i>r</i>', new THREE.Vector3(), { fontSize: '18px', background: 'rgba(255,255,255,0.75)' }),
  solidH: addLabel('<i>h</i>', new THREE.Vector3(), { fontSize: '18px', background: 'rgba(255,255,255,0.75)' }),
  netR: addLabel('<i>r</i>', new THREE.Vector3(), { fontSize: '16px', background: 'rgba(255,255,255,0.75)' }),
  netH: addLabel('<i>h</i>', new THREE.Vector3(), { fontSize: '16px', background: 'rgba(255,255,255,0.75)' }),
  netW: addLabel('2π<i>r</i>', new THREE.Vector3(), { fontSize: '16px', background: 'rgba(255,255,255,0.75)' }),
  capsTerm: addLabel('two caps: 2π<i>r</i><sup>2</sup>', new THREE.Vector3(), { fontSize: '14px', background: 'rgba(255,255,255,0.8)' }),
  sideTerm: addLabel('side: 2π<i>r</i><i>h</i>', new THREE.Vector3(), { fontSize: '14px', background: 'rgba(255,255,255,0.8)' }),
  formula: addLabel('<b>S = 2π<i>r</i><sup>2</sup> + 2π<i>r</i><i>h</i> = 2π<i>r</i>(<i>r</i> + <i>h</i>)</b>', new THREE.Vector3(), { fontSize: '15px', background: 'rgba(255,255,255,0.86)' })
};
labelsReady = true;

function updateLabels() {
  const topY = hVal / 2;
  const botY = -hVal / 2;
  const rightXZ = screenRight.clone().multiplyScalar(rVal);
