// @FIGURE_CODE_BEGIN
// top cap outline → full circular Line in horizontal XZ plane, black
// bottom cap outline → visible front semicircular Line in horizontal XZ plane, black
// left/right silhouette edges → vertical Line segments tangent to circular caps, black
// radius arrow → horizontal Line plus filled triangular arrowhead on top face, black
// height dimension arrow → vertical double-headed Line outside cylinder, black
// height extension lines → short horizontal Line segments from cylinder rim to dimension arrow at top and bottom levels, black
// invisible picking body → transparent CylinderGeometry matching the solid
// net cap circles → two screen-parallel Line loops, black
// net lateral rectangle → screen-parallel Line rectangle, black
// net dimension arrows → screen-parallel Line arrows for h and 2πr, black
// net circle radius arrow → screen-parallel Line plus triangular arrowhead, black
// formula association strokes → short Line connectors from circles/rectangle to formula terms, black

const black = 0x000000;
const solidGroup = new THREE.Group();
const netGroup = new THREE.Group();
scene.add(solidGroup);

const viewElevationDeg = 15.1;
const viewElevation = THREE.MathUtils.degToRad(viewElevationDeg);
const screenRight = new THREE.Vector3(1, 0, 0);
const screenUp = new THREE.Vector3(0, Math.cos(viewElevation), -Math.sin(viewElevation)).normalize();
const viewDir = new THREE.Vector3(0, Math.sin(viewElevation), Math.cos(viewElevation)).normalize();

let rVal = 1.25;
let hVal = 2.4;
let viewMode = 'Solid cylinder';
let targetNetBlend = 0;
let currentNetBlend = 0;
let fitAfterFade = false;
let labels = null;
let tweenToken = 0;

function disposeObject(obj) {
  obj.traverse?.(o => {
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
    else o.material?.dispose?.();
  });
}

function clearGroup(group) {
  while (group.children.length) {
    const child = group.children.pop();
    disposeObject(child);
  }
}

function lineMaterial(opacity = 1) {
  return new THREE.LineBasicMaterial({
    color: black,
    transparent: opacity < 1,
    opacity,
    depthTest: true
  });
}

function makeLine(parent, pts, opacity = 1) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMaterial(opacity));
  parent.add(line);
  return line;
}

function circleXZ(y, r, a0, a1, segments) {
  const pts = [];
  for (let i = 0; i <= segments; i++) {
    const t = a0 + (a1 - a0) * (i / segments);
    pts.push(new THREE.Vector3(r * Math.cos(t), y, r * Math.sin(t)));
  }
  return pts;
}

function screenPoint(x, y, normal = 0) {
  return screenRight.clone().multiplyScalar(x)
    .add(screenUp.clone().multiplyScalar(y))
    .add(viewDir.clone().multiplyScalar(normal));
}

function circleScreen(cx, cy, rr, segments = 128) {
  const pts = [];
  for (let i = 0; i <= segments; i++) {
    const t = Math.PI * 2 * i / segments;
    pts.push(screenPoint(cx + rr * Math.cos(t), cy + rr * Math.sin(t)));
  }
  return pts;
}

function rectScreen(cx, cy, w, h) {
  const x0 = cx - w / 2, x1 = cx + w / 2;
  const y0 = cy - h / 2, y1 = cy + h / 2;
  return [
    screenPoint(x0, y0), screenPoint(x1, y0),
    screenPoint(x1, y1), screenPoint(x0, y1),
    screenPoint(x0, y0)
  ];
}

function makeArrowHead(parent, tip, dir, opacity = 1, size = 0.12) {
  const d0 = dir.clone().normalize();
  const perp = viewDir.clone().cross(d0).normalize();
  const base = tip.clone().sub(d0.clone().multiplyScalar(size));
  const p1 = base.clone().add(perp.clone().multiplyScalar(size * 0.36));
  const p2 = base.clone().sub(perp.clone().multiplyScalar(size * 0.36));
  const geom = new THREE.BufferGeometry().setFromPoints([tip, p1, p2]);
  geom.setIndex([0, 1, 2]);
  geom.computeVertexNormals();
  const mat = new THREE.MeshBasicMaterial({
    color: black,
    side: THREE.DoubleSide,
    transparent: opacity < 1,
    opacity
  });
  const mesh = new THREE.Mesh(geom, mat);
  parent.add(mesh);
  return mesh;
}

function makeArrow(parent, start, end, { doubleHead = false, opacity = 1, size = 0.13, headDir = null } = {}) {
  const lineDir = end.clone().sub(start).normalize();
  const headDirection = (headDir || lineDir).clone().normalize();
  const trim = size * 0.78;
  const p0 = doubleHead ? start.clone().add(lineDir.clone().multiplyScalar(trim)) : start.clone();
  const p1 = end.clone().sub(lineDir.clone().multiplyScalar(trim));
  makeLine(parent, [p0, p1], opacity);
  makeArrowHead(parent, end, headDirection, opacity, size);
  if (doubleHead) makeArrowHead(parent, start, headDirection.clone().negate(), opacity, size);
}

function allMaterials(group) {
  const mats = [];
  group.traverse(o => {
    if (!o.material) return;
    if (Array.isArray(o.material)) mats.push(...o.material);
    else mats.push(o.material);
  });
  return mats;
}

function setGroupOpacity(group, opacity) {
  allMaterials(group).forEach(m => {
    m.transparent = true;
    m.opacity = opacity;
    m.needsUpdate = true;
  });
}

function fitCurrentView() {
  const wantSolid = currentNetBlend < 0.995 || targetNetBlend < 0.995;
  const wantNet = currentNetBlend > 0.005 || targetNetBlend > 0.005;
  if (wantSolid && !solidGroup.parent) scene.add(solidGroup);
  if (wantNet && !netGroup.parent) scene.add(netGroup);
  if (!wantSolid && solidGroup.parent) scene.remove(solidGroup);
  if (!wantNet && netGroup.parent) scene.remove(netGroup);

  setCameraView({
    projection: 'orthographic',
    azimuthDeg: 90,
    elevationDeg: viewElevationDeg,
    rollDeg: 0,
    target: [0, 0, 0],
    heightFraction: viewMode === 'Surface-area net' ? 0.74 : 0.86,
    distanceScale: 1.25
  });
}

function updateReadouts() {
  document.getElementById('radiusVal').textContent = rVal.toFixed(2);
  document.getElementById('heightVal').textContent = hVal.toFixed(2);
  const caps = 2 * Math.PI * rVal * rVal;
  const side = 2 * Math.PI * rVal * hVal;
  document.getElementById('areaOut').innerHTML =
    `S = ${caps.toFixed(2)} + ${side.toFixed(2)} = ${(caps + side).toFixed(2)}`;
}

function updateLabels() {
  if (!labels) return;

  const topY = hVal / 2;
  const botY = -hVal / 2;
  const arrowX = rVal + 0.35;

  labels.solidR.pos.copy(new THREE.Vector3(rVal * 0.66, topY, 0));
  labels.solidH.pos.copy(new THREE.Vector3(arrowX, (topY + botY) / 2, 0));

  const cR = rVal * 0.55;
  const rectW = 2 * Math.PI * rVal * 0.32;
  const rectH = hVal;
  const circleX = -1.8;
  const circleY = cR + 0.18;
  const rectX = 1.5;
  const rectY = 0.08;

  labels.netR.pos.copy(screenPoint(circleX + cR * 0.58, circleY + 0.05));
  labels.netH.pos.copy(screenPoint(rectX + rectW / 2 + 0.34, rectY));
  labels.netW.pos.copy(screenPoint(rectX, rectY - rectH / 2 - 0.30));
  labels.capsTerm.pos.copy(screenPoint(circleX, -circleY - cR - 0.22));
  labels.sideTerm.pos.copy(screenPoint(rectX, rectY - rectH / 2 - 0.50));
  labels.formula.pos.copy(screenPoint(0.48, rectY - rectH / 2 - 0.88));

  const solidOpacity = Math.max(0, Math.min(1, 1 - currentNetBlend));
  const netOpacity = Math.max(0, Math.min(1, currentNetBlend));

  [labels.solidR, labels.solidH].forEach(l => {
    l.div.style.opacity = solidOpacity;
    l.div.style.visibility = solidOpacity > 0.06 ? 'visible' : 'hidden';
  });
  [labels.netR, labels.netH, labels.netW, labels.capsTerm, labels.sideTerm, labels.formula].forEach(l => {
    l.div.style.opacity = netOpacity;
    l.div.style.visibility = netOpacity > 0.06 ? 'visible' : 'hidden';
  });
}

function rebuildGeometry(refit = false) {
  clearGroup(solidGroup);
  clearGroup(netGroup);

  const topY = hVal / 2;
  const botY = -hVal / 2;
  const arrowX = rVal + 0.35;

  makeLine(solidGroup, circleXZ(topY, rVal, 0, Math.PI * 2, 192), 1);
  makeLine(solidGroup, circleXZ(botY, rVal, 0, Math.PI, 96), 1);
  makeLine(solidGroup, [new THREE.Vector3(-rVal, topY, 0), new THREE.Vector3(-rVal, botY, 0)], 1);
  makeLine(solidGroup, [new THREE.Vector3(rVal, topY, 0), new THREE.Vector3(rVal, botY, 0)], 1);

  makeArrow(
    solidGroup,
    new THREE.Vector3(0, topY, 0),
    new THREE.Vector3(rVal, topY, 0),
    { doubleHead: false, opacity: 1, size: 0.115, headDir: screenRight }
  );

  makeLine(solidGroup, [new THREE.Vector3(rVal, topY, 0), new THREE.Vector3(arrowX, topY, 0)], 1);
  makeLine(solidGroup, [new THREE.Vector3(rVal, botY, 0), new THREE.Vector3(arrowX, botY, 0)], 1);
  makeArrow(
    solidGroup,
    new THREE.Vector3(arrowX, botY, 0),
    new THREE.Vector3(arrowX, topY, 0),
    { doubleHead: true, opacity: 1, size: 0.12, headDir: screenUp }
  );

  const pickMesh = new THREE.Mesh(
    new THREE.CylinderGeometry(rVal, rVal, hVal, 64, 1, false),
    new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, depthWrite: false })
  );
  registerInteractive(pickMesh, {
    title: 'Cylinder measurements',
    tooltip: 'Cylinder: radius r and height h',
    body: 'The radius r measures from the center of a circular cap to its rim. The height h measures the distance between the two circular caps.'
  });
  solidGroup.add(pickMesh);

  const cR = rVal * 0.55;
  const rectW = 2 * Math.PI * rVal * 0.32;
  const rectH = hVal;
  const circleX = -1.8;
  const circleY = cR + 0.18;
  const rectX = 1.5;
  const rectY = 0.08;

  makeLine(netGroup, circleScreen(circleX, circleY, cR), 1);
  makeLine(netGroup, circleScreen(circleX, -circleY, cR), 1);
  makeLine(netGroup, rectScreen(rectX, rectY, rectW, rectH), 1);

  makeArrow(
    netGroup,
    screenPoint(circleX, circleY),
    screenPoint(circleX + cR, circleY),
    { doubleHead: false, opacity: 1, size: 0.095, headDir: screenRight }
  );
  makeArrow(
    netGroup,
    screenPoint(rectX + rectW / 2 + 0.22, rectY - rectH / 2),
    screenPoint(rectX + rectW / 2 + 0.22, rectY + rectH / 2),
    { doubleHead: true, opacity: 1, size: 0.095, headDir: screenUp }
  );
  makeArrow(
    netGroup,
    screenPoint(rectX - rectW / 2, rectY - rectH / 2 - 0.20),
    screenPoint(rectX + rectW / 2, rectY - rectH / 2 - 0.20),
    { doubleHead: true, opacity: 1, size: 0.095, headDir: screenRight }
  );

  makeLine(netGroup, [
    screenPoint(circleX + cR * 0.25, -circleY - cR - 0.04),
    screenPoint(circleX + 0.05, -circleY - cR - 0.22)
  ], 1);
  makeLine(netGroup, [
    screenPoint(rectX, rectY - rectH / 2 - 0.04),
    screenPoint(rectX, rectY - rectH / 2 - 0.38)
  ], 1);

  registerInteractive(netGroup, {
    title: 'Surface-area net',
    tooltip: 'Net: two circles plus one rectangle',
    body: 'The two circular caps contribute 2πr². The unwrapped side is a rectangle of height h and width 2πr, so its area is 2πrh.'
  });

  setGroupOpacity(solidGroup, 1 - currentNetBlend);
  setGroupOpacity(netGroup, currentNetBlend);
  pickMesh.material.opacity = 0;

  updateReadouts();
  updateLabels();
  if (refit) fitCurrentView();
}

rebuildGeometry(false);
fitCurrentView();

labels = {
  solidR: addLabel('<i>r</i>', new THREE.Vector3(), {
    fontSize: '26px',
    color: '#000',
    bold: true,
    offset: [0, -18]
  }),
  solidH: addLabel('<i>h</i>', new THREE.Vector3(), {
    fontSize: '27px',
    color: '#000',
