    offset: [26, 0]
  }),
  netR: addLabel('<i>r</i>', new THREE.Vector3(), {
    fontSize: '18px',
    color: '#000',
    bold: true,
    offset: [0, -12]
  }),
  netH: addLabel('<i>h</i>', new THREE.Vector3(), {
    fontSize: '18px',
    color: '#000',
    bold: true,
    offset: [16, 0]
  }),
  netW: addLabel('2π<i>r</i>', new THREE.Vector3(), {
    fontSize: '18px',
    color: '#000',
    bold: true,
    offset: [0, 12]
  }),
  capsTerm: addLabel('two caps: 2π<i>r</i><sup>2</sup>', new THREE.Vector3(), {
    fontSize: '14px',
    color: '#000',
    background: 'rgba(255,255,255,0.82)'
  }),
  sideTerm: addLabel('side: 2π<i>r</i><i>h</i>', new THREE.Vector3(), {
    fontSize: '14px',
    color: '#000',
    background: 'rgba(255,255,255,0.82)'
  }),
  formula: addLabel('<b>S = 2π<i>r</i><sup>2</sup> + 2π<i>r</i><i>h</i> = 2π<i>r</i>(<i>r</i> + <i>h</i>)</b>', new THREE.Vector3(), {
    fontSize: '15px',
    color: '#000',
    background: 'rgba(255,255,255,0.88)'
  })
};
updateLabels();

document.getElementById('btnReset').style.display = '';

function setMode(next) {
  viewMode = next;
  targetNetBlend = next === 'Surface-area net' ? 1 : 0;
  fitAfterFade = true;
  document.getElementById('viewMode').textContent =
    next === 'Surface-area net' ? 'Solid cylinder' : 'Surface-area net';
  if (!solidGroup.parent) scene.add(solidGroup);
  if (!netGroup.parent) scene.add(netGroup);
  fitCurrentView();
}

document.getElementById('radius').addEventListener('input', e => {
  rVal = Number(e.target.value);
  rebuildGeometry(true);
});

document.getElementById('height').addEventListener('input', e => {
  hVal = Number(e.target.value);
  rebuildGeometry(true);
});

document.getElementById('viewMode').addEventListener('click', () => {
  setMode(viewMode === 'Surface-area net' ? 'Solid cylinder' : 'Surface-area net');
});

const demoSteps = [
  {
    title: 'Identify the two measurements',
    narration: 'In the solid-cylinder view, r is the distance from the center of the top circular face to its rim, while h is the vertical distance between the two rims.',
    state: { radius: 1.25, height: 2.4, viewMode: 'Solid cylinder' }
  },
  {
    title: 'Increase the radius',
    narration: 'As r grows, the top and bottom caps widen, and the cylinder’s circumference also grows. This shows why r appears in both the cap term and the side term.',
    state: { radius: 1.8, height: 2.4, viewMode: 'Solid cylinder' }
  },
  {
    title: 'Increase the height',
    narration: 'As h grows, the cylinder stretches upward but the circular caps do not change. Only the side surface gains area.',
    state: { radius: 1.25, height: 3.5, viewMode: 'Solid cylinder' }
  },
  {
    title: 'Unwrap the surface',
    narration: 'The same measurements form the net: two circles of radius r plus one rectangle of height h and width 2πr. Adding those areas gives S = 2πr² + 2πrh = 2πr(r + h).',
    state: { radius: 1.25, height: 2.4, viewMode: 'Surface-area net' }
  }
];

window.goToStep = function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  tweenToken++;
  const token = tweenToken;
  const startR = rVal;
  const startH = hVal;
  const endR = step.state.radius;
  const endH = step.state.height;
  const start = performance.now();

  document.getElementById('stepNarration').innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  setMode(step.state.viewMode);

  function tick(now) {
    if (token !== tweenToken) return;
    const t = Math.min(1, (now - start) / 760);
    const ease = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    rVal = startR + (endR - startR) * ease;
    hVal = startH + (endH - startH) * ease;
    document.getElementById('radius').value = rVal.toFixed(2);
    document.getElementById('height').value = hVal.toFixed(2);
    rebuildGeometry(false);
    if (t < 1) {
      requestAnimationFrame(tick);
    } else {
      rVal = endR;
      hVal = endH;
      document.getElementById('radius').value = rVal;
      document.getElementById('height').value = hVal;
      rebuildGeometry(true);
    }
  }
  requestAnimationFrame(tick);
};

document.querySelectorAll('.stepBtn').forEach(btn => {
  btn.addEventListener('click', () => window.goToStep(Number(btn.dataset.step)));
});

function fadeLoop() {
  requestAnimationFrame(fadeLoop);
  const before = currentNetBlend;
  currentNetBlend += (targetNetBlend - currentNetBlend) * 0.13;
  if (Math.abs(currentNetBlend - targetNetBlend) < 0.002) currentNetBlend = targetNetBlend;

  if (currentNetBlend !== before) {
    setGroupOpacity(solidGroup, 1 - currentNetBlend);
    setGroupOpacity(netGroup, currentNetBlend);
    solidGroup.traverse(o => {
      if (o.isMesh && o.material && o.material.opacity === 0) o.material.opacity = 0;
    });
    updateLabels();
  }

  if (fitAfterFade && currentNetBlend === targetNetBlend) {
    fitAfterFade = false;
    if (targetNetBlend === 0 && netGroup.parent) scene.remove(netGroup);
    if (targetNetBlend === 1 && solidGroup.parent) scene.remove(solidGroup);
    fitCurrentView();
  }
}
fadeLoop();

document.getElementById('stepNarration').innerHTML =
  `<b>${demoSteps[0].title}</b><br>${demoSteps[0].narration}`;
// @FIGURE_CODE_END

